UPDATE products p JOIN categories c ON p.category_id = c.id SET p.category = c.name WHERE p.category = '' OR p.category IS NULL;

ON DUPLICATE KEY UPDATE nama_kasir = VALUES(nama_kasir);

ON DUPLICATE KEY UPDATE nama_supplier = VALUES(nama_supplier);
